def sumofFactors(n):
    # Initialize result
    result = 0

    # Iterate through all numbers from 1 to n
    for i in range(1, n + 1):
        # Check if i is a factor of n
        if n % i == 0:
            # Check if i is an even number
            if i % 2 == 0:
                # Add i to the result
                result += i

    # Return the sum of even factors
    return result

def newman_prime(n):
    """
    Find the nth Newman–Shanks–Williams prime number.

    Args:
    n (int): The position of the Newman–Shanks–Williams prime number to find.

    Returns:
    int: The nth Newman–Shanks–Williams prime number.

    Raises:
    ValueError: If n is less than 1.
    """
    if n < 1:
        raise ValueError("n must be greater than or equal to 1")

    memo = {0: 0, 1: 1}

    def is_prime(num):
        """Check if a number is prime."""
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def nsw_number(k):
        """Calculate the kth Newman–Shanks–Williams number with memoization."""
        if k in memo:
            return memo[k]
        memo[k] = nsw_number(k - 1) + nsw_number(k - 2) + 1
        return memo[k]

    count = 0
    k = 0
    while True:
        nsw = nsw_number(k)
        if is_prime(nsw):
            count += 1
            if count == n:
                return nsw
        k += 1

def two_unique_nums(nums):
    """
    Removes duplicate numbers from a given list of numbers.

    Args:
    nums (list): A list of integers.

    Returns:
    list: A list of integers with duplicates removed.

    Raises:
    TypeError: If the input is not a list.
    ValueError: If the list contains non-integer elements.
    """
    if not isinstance(nums, list):
        raise TypeError("Input must be a list.")

    if not all(isinstance(x, int) for x in nums):
        raise ValueError("List must contain only integers.")

    counts = {}
    for num in nums:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    return [num for num, count in counts.items() if count == 2]

def count_Occurrence(test_tup, K):
    # Initialize result dictionary
    res = dict()
    
    # Iterate over each element in the tuple
    for ele in test_tup:
        # If the element is in the list K, count its occurrences
        if ele in K:
            # If the element is already in the dictionary, increment its count
            if ele in res:
                res[ele] += 1
            # If the element is not in the dictionary, add it with a count of 1
            else:
                res[ele] = 1
    
    # Return the sum of the counts of all elements in K found in the tuple
    return sum(res.values())
